import React, { useState } from 'react';

const RegistroEstudianteForm = () => {
  const [step, setStep] = useState(1);

  const steps = [
    'Datos del Estudiante',
    'Datos del Nacimiento',
    'Dirección Actual',
    'Datos del Tutor',
  ];

  const handleNext = () => setStep((prev) => Math.min(prev + 1, steps.length));
  const handlePrev = () => setStep((prev) => Math.max(prev - 1, 1));

  const Tabs = () => (
    <div className="flex justify-between mb-6">
      {steps.map((label, index) => (
        <div
          key={index}
          className={`flex-1 text-center p-2 border-b-4 transition-all duration-300 ${
            step === index + 1 ? 'border-blue-500 font-bold text-blue-600' : 'border-gray-300 text-gray-500'
          }`}
        >
          {label}
        </div>
      ))}
    </div>
  );

  const Buttons = ({ isFinalStep }) => (
    <div className="flex justify-between mt-6">
      <button onClick={handlePrev} disabled={step === 1} className="bg-gray-300 text-gray-800 px-4 py-2 rounded disabled:opacity-50">
        Anterior
      </button>
      <button onClick={handleNext} className="bg-blue-500 text-white px-4 py-2 rounded">
        {isFinalStep ? 'Finalizar' : 'Siguiente'}
      </button>
    </div>
  );

  const SaveCancel = () => (
    <div className="flex justify-end space-x-4 mt-4">
      <button className="bg-green-500 text-white px-4 py-2 rounded">Guardar</button>
      <button className="bg-red-500 text-white px-4 py-2 rounded">Cancelar</button>
    </div>
  );

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="w-full max-w-6xl bg-white shadow-xl p-10 rounded-2xl">
        <Tabs />
        {step === 1 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input placeholder="Apellido Paterno" className="input" />
            <input placeholder="Apellido Materno" className="input" />
            <input placeholder="Nombres" className="input" />
            <input placeholder="RUDE" className="input" />
            <div className="flex gap-2">
              <input placeholder="CI" className="input w-1/2" />
              <input placeholder="Expedido" className="input w-1/4" />
              <input placeholder="Complemento" className="input w-1/4" />
            </div>
            <input type="date" className="input" placeholder="Fecha de Nacimiento" />
            <select className="input">
              <option>Seleccionar Género</option>
              <option>Masculino</option>
              <option>Femenino</option>
              <option>Otro</option>
            </select>
          </div>
        )}

        {step === 2 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input placeholder="País" className="input" />
            <input placeholder="Lugar de Nacimiento" className="input" />
            <input placeholder="Nro de Oficialía" className="input" />
            <input placeholder="Nro de Libro" className="input" />
            <input placeholder="Nro de Partida" className="input" />
            <input placeholder="Nro de Folio" className="input" />
            <div>
              <label className="block mb-2 text-sm text-gray-600">Adjuntar Documentación</label>
              <input type="file" className="input" />
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input placeholder="Ciudad / Municipio" className="input" />
            <input placeholder="Localidad / Comunidad" className="input" />
            <input placeholder="Zona / Urbanización / Villa" className="input" />
            <input placeholder="Avenida / Calle" className="input" />
            <input placeholder="Número de Vivienda" className="input" />
            <div>
              <label className="block mb-2 text-sm text-gray-600">Adjuntar Documentación</label>
              <input type="file" className="input" />
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input placeholder="Apellido Paterno" className="input" />
            <input placeholder="Apellido Materno" className="input" />
            <input placeholder="Nombres" className="input" />
            <div className="flex gap-2">
              <input placeholder="CI" className="input w-1/2" />
              <input placeholder="Complemento" className="input w-1/4" />
              <input placeholder="Expedido" className="input w-1/4" />
            </div>
            <input type="email" placeholder="Correo" className="input" />
            <input placeholder="Celular" className="input" />
            <input type="date" className="input" placeholder="Fecha de Nacimiento" />
            <select className="input">
              <option>Seleccionar Género</option>
              <option>Masculino</option>
              <option>Femenino</option>
              <option>Otro</option>
            </select>
            <select className="input">
              <option>Relación</option>
              <option>Padre</option>
              <option>Madre</option>
              <option>Tutor</option>
              <option>Apoderado</option>
            </select>
          </div>
        )}

        <Buttons isFinalStep={step === 4} />
        <SaveCancel />
      </div>
    </div>
  );
};

export default RegistroEstudianteForm;

// Estilo auxiliar
// Puedes agregar en tu CSS o tailwind.config
// .input { @apply w-full p-2 border rounded-md border-gray-300 focus:outline-none focus:ring focus:border-blue-400; }
